import './App.css';
import { BrowserRouter as Router, Route, Routes, useParams } from "react-router-dom";
import Home from './Components/Home/Home'
import TerminalComponent from './Components/TerminalComponent/TerminalComponent'
function App() {
  function getcontainerId() {
    // 👇️ get ID from url
    const params = useParams();

    console.log("params",  params.containerId); // 👉️ {userId: '4200'}

    return <h2>userId is 👉️ {params.containerId}</h2>;
  }
  return (
    <div className="App">
       <Router>
      <Routes>
        <Route exact path="/" element={<Home/>} />
        <Route exact path="/new/:containerId" element = {<TerminalComponent/>}/>
      </Routes>
    </Router>
    </div>
  );
}

export default App;
